INSERT INTO mdm.product_master_field (field_order, source_field, column_name, description) VALUES
    (1, N'Product_Family', N'product_hierarchy (level 1)', N'Broad product portfolio or business-line grouping within Gradian Thermal Solutions. Entries include Air Cooling, Liquid Cooling, Chillers, Prefabricated Solutions, Commissioning and Services Solutions, and legacy brand families such as Daedex, DeepCoolAI, Ecochillers, and MAS Custom. It distinguishes the major thermal-management offerings for portfolio reporting and planning.'),
    (2, N'Product_Type', N'product_hierarchy (level 2)', N'The equipment or service category within a product family. Examples include AHU (air handling unit), CRAH (computer room air handler), chillers, fluid coolers, CDU (coolant distribution unit), load banks, manifolds, and commissioning. It identifies what Gradian supplies, separating air-side cooling, liquid-cooling equipment, heat rejection, accessories, and services.'),
    (3, N'Model', N'product_hierarchy (level 3)', N'The design, configuration, or equipment variant within the product type. Current examples include Indoor, Outdoor, Ceiling Hung, Dry Cooler, Centrifugal, Scroll, and CDU Skid. For Gradian''s configured thermal systems, this distinguishes installation arrangements, cooling technologies, or assembly styles; it is not consistently a manufacturer model number. Some records are blank.'),
    (4, N'Size', N'product_hierarchy (level 4)', N'The capacity, size band, complexity level, or custom configuration that differentiates a product variant. Entries include kW ranges, T ratings, High/Medium/Low Complexity, and Custom. For Gradian, this helps distinguish cooling duty or build complexity. The field mixes measures and descriptors, so units and meaning must be read with Product_Type and Model; some entries are blank.'),
    (5, N'SIOP_Model', N'siop_model', N'Internal product-model grouping code intended for SIOP (Sales, Inventory and Operations Planning), inferred from the field name and repeated codes such as 100, 110, and 570. It can group Gradian product variants for demand and supply planning rather than identify one catalog record. The official code-to-planning-group mapping is not documented in this workbook.'),
    (6, N'SIOP_Tier', N'siop_tier', N'An additional SIOP planning classification. Populated entries include 1, 2, 3, ASIA, and Asia, while most records are blank. For Gradian, it appears to further segment planning groups, but the mix of numeric tiers and geographic labels means it should not be assumed to be a uniform complexity or priority scale without an internal definition.'),
    (7, N'Product_Name', N'product_name', N'The human-readable product label, generally combining family, type, model, and size or complexity. Examples describe air handlers, chillers, liquid-cooling assemblies, and accessories. It gives Gradian teams a recognizable configuration name for catalogs and planning. All current records have distinct names, although some names retain legacy brand terminology.'),
    (8, N'Product_Code', N'product_code', N'The internal product identifier or catalog code, such as 1001 or 5035. It provides a compact reference for Gradian product records and potential links to quoting, ordering, or planning systems. Codes repeat across some records in this master, so this column alone should not be treated as a unique row key without confirming the intended mapping.'),
    (9, N'Sections_Per_Unit', N'sections_per_unit', N'The number of physical sections or modules associated with one finished unit. Current entries are 1 or 5, stored as text. For Gradian''s modular air-handling and custom thermal equipment, this is intended to distinguish a single-section unit from a multi-section build for production planning. The precise section-counting convention requires confirmation.'),
    (10, N'Sale_Price_Per_Unit', N'sale_price_per_unit', N'The stored selling-price assumption for one product unit. Current values include 75,000, 85,000, 120,000, and 650,000. It can support Gradian sales-value and product-mix planning across thermal equipment. The workbook does not specify currency, effective date, or whether prices are list prices, averages, or planning defaults; do not treat them as confirmed customer quotations.'),
    (11, N'Sale_Price_Per_Hour', N'sale_price_per_hour', N'The stored sales-value rate per hour, with current values of 700, 900, and 1,100. For Gradian, it may support revenue-per-hour or capacity-based planning across equipment categories. It is labeled as a sales rate, not labor cost. Currency, the type of hour, and the relationship to unit pricing are not defined in the workbook.'),
    (12, N'Default_Supply_Source', N'default_supply_source', N'The default supply-source code assigned to the product, currently DATN or MPGR. It indicates the source to use as a starting point when planning supply for Gradian equipment. The workbook does not define whether these codes refer to plants, suppliers, or other supply locations, so their full names and routing implications need internal confirmation.'),
    (13, N'Est_Fab_Hours', N'est_fab_hours', N'Estimated fabrication labor hours for a product unit or configuration, with current entries including 12, 16, 18, 24, 30, and 50, as well as zero. For Gradian, this is intended to represent fabrication workload, such as making structural or enclosure parts before assembly. Confirm the per-unit basis; zero entries do not by themselves prove fabrication is unnecessary.'),
    (14, N'Est_Assembly_Hours', N'est_assembly_hours', N'Estimated assembly labor hours for a product unit or configuration. Nonzero entries include 20, 36, 40, 48, 60, and 100. For Gradian, this is intended to represent the effort to assemble cooling equipment, modules, and components for production capacity planning. Confirm whether testing or commissioning is included; zero entries are not proof of no assembly work.'),
    (15, N'Fab_Lbr_Hrs_%', N'fab_lbr_hrs_pct', N'A field intended to express a fabrication labor-hours percentage or allocation factor. For Gradian, it would distinguish fabrication''s share of a defined labor or planning base. Every current entry is zero, and the denominator and calculation rule are not documented. Do not assume it equals Est_Fab_Hours divided by total labor hours without confirmation.'),
    (16, N'Assmb_Lbr_Hrs_%', N'assmb_lbr_hrs_pct', N'A field intended to express an assembly labor-hours percentage or allocation factor. For Gradian, it would distinguish assembly''s share of a defined labor or planning base. Every current entry is zero, and the denominator and calculation rule are not documented. Its relationship to Est_Assembly_Hours and the fabrication percentage requires an internal definition.'),
    (17, N'Qty_Fans', N'qty_fans', N'The fan quantity associated with the product configuration, with current entries ranging from zero to 10. Fans are relevant to moving air through Gradian air handlers, fan-coil equipment, and heat-rejection systems. This field can support component-demand planning but is not a complete bill of materials; confirm whether zero means not applicable or not yet populated.'),
    (18, N'Qty_Coils', N'qty_coils', N'The coil quantity associated with the product configuration, currently zero, one, or two. Coils provide heat exchange in applicable Gradian air-side cooling and thermal equipment. This count can support component and production planning, but it does not describe coil type, dimensions, or thermal performance. Zero entries require interpretation in the context of the product.'),
    (19, N'Qty_Panels', N'qty_panels', N'The panel quantity associated with the product configuration, currently zero or one. It is intended to capture a panel-related component count for Gradian production planning. The master does not specify whether a panel is an enclosure panel, electrical/control panel, or another assembly; confirm the component definition before using this field for material requirements.'),
    (20, N'Standard_Unit_Multiplier', N'standard_unit_multiplier', N'The factor intended to convert a physical product unit into a standard planning-unit equivalent, currently 1 or 2. For Gradian, it could normalize different thermal-equipment configurations for comparable workload or capacity reporting. The reference standard and conversion method are not documented, so this should not be interpreted as physical section count or cooling capacity.'),
    (21, N'Status', N'status', N'The product record''s lifecycle or availability classification: Active, Inactive, or Archived. It helps Gradian distinguish current offerings from records retained for history or not presently in use. Planning and catalog reports can filter by this field, but the exact approval rules and the operational difference between Inactive and Archived need internal confirmation.'),
    (22, N'Capacity Group', N'capacity_group', N'The grouping intended for production-capacity reporting, distinct from the broad Product_Family and the configuration-level Product_Name. Examples include AHU, Chiller, CDU, CDU Skid, Manifolds, Sourced, and Rack Frame / Accessories. It can consolidate Gradian products into workload categories, but it does not itself contain thermal output or available factory capacity.');
